from pathlib import Path
import json
import re
from html import escape as e
from urllib.parse import urlencode
R=Path(__file__).resolve().parents[1]
book=json.loads((R/'content/book.json').read_text())
d=json.loads((R/'content/collection.json').read_text()); images={x['id']:x for x in d['images']}
def image_path(id):
 return images[id].get('path',f'assets/{id}.jpg')
def fig(id):
 x=images[id]
 return f'<figure><a href="{image_path(id)}"><img src="{image_path(id)}" alt="{e(x["title"])}" loading="lazy" width="1800" height="1200"></a><figcaption>{e(x["title"])} · {e(x["date"])}. <a href="documents/pars-from-the-past.pdf#page={int(re.search(r"\d+",str(x["page"]))[0])}">Pars from the Past, p. {e(x["page"])}</a>. <a href="archive.html#{id}">Image record ↗</a></figcaption></figure>'
def cards(items):return '<div class="cards">'+''.join(f'<a class="card" href="{x["id"]}.html">'+(f'<img src="{image_path(x["image"])}" alt="" loading="lazy">' if x['image'] else f'<div class="type-image">{e(x["date"].split(" · ")[0])}</div>')+f'<div><span class="eyebrow">{e(x["date"])}</span><h3>{e(x["title"])}</h3><p>{e(x["intro"])}</p><span class="read">Read the story →</span></div></a>' for x in items)+'</div>'
def recent_records(group):
 records=sorted((x for x in d.get('records',[]) if group in x.get('groups',[]) and x.get('review_status')=='approved'),key=lambda x:x['date'],reverse=True)
 if not records:return '<p class="quiet">No recent records added yet. This area will hold dated contributions, results, photographs and accounts of club activities.</p>'
 return ''.join(f'<article class="club-record"><span class="eyebrow">{e(x["date"])}</span><h3>{e(x["title"])}</h3><p>{e(x["summary"])}</p><details><summary>Read the record</summary><p>{e(x["body"])}</p><p class="source">Contributor: {e(x["contributor"])} · Source: {e(x["source"])}</p></details></article>' for x in records)
def group_book_links(group):
 chapters={'juniors':[(18,'Personal experiences'),(12,'Resident professionals')],'ladies':[(8,'Women’s golf'),(10,'The women veterans'),(24,'The Una Wickham Memorial Tournament')],'ladies-nine-hole':[(8,'Women’s golf and nine-hole origins')],'men':[(7,'Men’s golf'),(19,'The Ward dynasty')],'senior-men':[(9,'Veteran men’s golf')]}
 links=''.join(f'<p><a href="book-{n:02}.html">{e(title)} · Original book →</a></p>' for n,title in chapters.get(group,[]))
 if group=='ladies-nine-hole':links+='<p><a href="book-page-106.html">Phyll Sandlant’s own account · p. 106 →</a></p>'
 if group=='juniors':links+='<p><a href="book-page-173.html">Junior championship eligibility · p. 173 →</a></p><p><a href="book-page-281.html">Juniors and the changing culture · p. 281 →</a></p>'
 return '<h3>More from Dave’s book</h3>'+links
nav=[('index.html','Home'),('subjects.html','Subjects'),('people-index.html','People'),('timeline.html','Timeline'),('archive.html','Documents & photos'),('search.html','Search')]
def page(file,title,body):
 # Subject references open the original PDF; the text view remains a secondary option.
 if not re.fullmatch(r'book-(?:page-\d{3}|\d{2})\.html',file) and file!='book.html':
  body=re.sub(r'<a href="book-page-(\d{3})\.html">(.*?)</a>',lambda m:f'<a href="documents/pars-from-the-past.pdf#page={int(m[1])}">{m[2]}</a> <a class="source-text-link" href="book-page-{m[1]}.html" aria-label="Text view of book page {int(m[1])}">Text view</a>',body,flags=re.S)
 body=re.sub(r'href="(documents/[^"]+\.pdf)#page=(\d+)"',lambda m:f'href="pdf-viewer/web/viewer.html?file=../../{m[1]}#page={m[2]}"',body)
 body_class='source-reader' if file.startswith('book-page-') else ''
 feedback_url='https://github.com/bwucee/Tauranga-Golf-Club-Heritage/issues/new?'+urlencode({'template':'member-feedback.yml','title':'Feedback: '+title,'page':file})
 links=''.join(f'<a href="{p}"'+(' aria-current="page"' if p==file else '')+f'>{n}</a>' for p,n in nav)
 html=f'''<!doctype html><html lang="en-NZ"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>{e(title)} | Tauranga Golf Club Heritage</title><meta name="description" content="Explore Tauranga Golf Club’s history and continuing story through people, photographs and club records."><link rel="stylesheet" href="assets/style.css"></head><body class="{body_class}"><a class="skip" href="#main">Skip to content</a><div class="preview">WORKING PREVIEW <span>Member review edition · The book and our continuing history</span></div><header><a class="brand" href="index.html"><img class="club-logo" src="assets/club-logo.jpg" alt="Tauranga Golf Club"><span class="collection-label">HERITAGE &amp; CLUB LIFE</span></a><a class="club-link" href="https://www.taurangagolf.co.nz/">Club website ↗</a></header><nav aria-label="Heritage collection">{links}</nav><div class="collection-shortcuts" aria-label="More ways into the collection"><a href="book.html">Dave’s book</a><a href="history.html">Browse eras</a><a href="club.html">Club groups</a><a href="course.html">The course</a><a href="editorial-updates.html">Contributions &amp; corrections</a><a href="feedback.html">Share a memory</a><a href="sources.html">Sources &amp; notes</a><a href="https://www.taurangagolf.co.nz/history?ComeFromCat=1338">Club History ↗</a></div><main id="main">{body}<aside class="feedback-invite"><h2>Help this collection grow.</h2><p>A correction, a name for a face, or a story to add? Your knowledge can make the record richer.</p><a href="{e(feedback_url)}">Comment on this page via GitHub ↗</a> · <a href="feedback.html">Other ways to share feedback</a></aside></main><footer><div><strong>Tauranga Golf Club</strong><p>Heritage &amp; Club Life · Building on Pars from the Past</p></div><div><a href="subjects.html">Browse by subject</a><br><a href="people-index.html">Find a person</a><br><a href="editorial-updates.html">Contributions &amp; corrections</a><br><a href="book.html">Explore Dave’s book</a><br><a href="search.html">Search the collection</a><br><a href="feedback.html">Share feedback or a memory</a><br><a href="sources.html">Sources & editorial notes</a><br><a href="https://www.taurangagolf.co.nz/history?ComeFromCat=1338">Return to the club’s History page ↗</a></div><p class="fine">Member review edition · Historical text remains open to correction. Images authorised for publication.</p></footer><script src="assets/site.js" defer></script></body></html>'''
 (R/file).write_text(html)
def heading(k,t,p):return f'<div class="page-heading"><span class="eyebrow">{k}</span><h1>{t}</h1><p class="lead">{p}</p></div>'
page('index.html','Heritage & Club Life','''<section class="hero"><div class="hero-copy"><span class="eyebrow">HERITAGE &amp; CLUB LIFE</span><h1>Our club.<br>Our continuing story.</h1><p class="lead">From the first fairways to the people playing today. Begin with a moment, a place or a part of the club, and follow what interests you.</p><a class="button" href="subjects.html">Explore by subject <span>→</span></a><a class="secondary-link" href="club.html">Find your part of the club →</a><p class="hero-note">The 2014 book, earlier sources and later contributions</p></div><figure><img src="assets/domain.jpg" alt="Two early golfers below The Elms, with the estuary behind them" width="1800" height="1137" fetchpriority="high"><figcaption>E. T. Baker &amp; H. B. Mountfort · c.1904–1913<br>A. J. Mirrielees · Pars from the Past, p. 1</figcaption></figure></section><section class="book-credit"><span class="eyebrow">BUILT ON DAVE MOWAT’S WORK</span><h2>A book that gave our history a home.</h2><p>Dave Mowat devoted years to bringing together <em>Pars from the Past</em>, published in 2014 to celebrate one hundred years of golf at Gate Pa. This collection builds on that work, preserving its source references as we add more of the club’s continuing story.</p><a href="book.html">Explore Dave’s book →</a> · <a href="about.html">About the collection</a></section><section><div class="section-head"><div><span class="eyebrow">CHOOSE YOUR WAY IN</span><h2>A little at a time.</h2></div></div><div class="explore-doors"><a href="subjects.html"><span class="eyebrow">01 · THROUGH SUBJECTS</span><h3>Find your interest</h3><p>Greenkeeping, professionals, life members, volunteers and benefactors, course development and tournaments.</p><span class="read">Browse the subject index →</span></a><a href="club.html"><span class="eyebrow">02 · THROUGH PEOPLE</span><h3>Our club</h3><p>Juniors, Ladies, Ladies 9 Hole, Men and Senior Men: their stories, achievements and records.</p><span class="read">Find a club group →</span></a><a href="archive.html"><span class="eyebrow">03 · THROUGH PICTURES</span><h3>The archive</h3><p>Look closer at the photographs and documents behind the stories.</p><span class="read">Browse the archive →</span></a></div></section><section class="featured-story"><img src="assets/avenue.jpg" alt="The original first hole, The Avenue; photograph undated" loading="lazy"><div><span class="eyebrow">A STORY TO START WITH · 1914</span><h2>A new home at Gate Pa.</h2><p>Members turned exposed reserve land into a place for golf. Follow the move that shaped the club.</p><a class="read" href="gate-pa.html">Read the story →</a></div></section>''')
page('history.html','Our history',heading('THE HISTORICAL FRAMEWORK','One chapter at a time.','Start with an era. Within each chapter, follow the timeline or explore the course, people and photographs.')+'<div class="reader-tools"><a href="timeline.html">Follow the complete timeline →</a><a href="book.html">Browse the book by subject →</a></div><div class="era-list">'+''.join((f'<a class="era" href="{x["link"]}">' if x.get('link') else '<div class="era planned">')+f'<span class="year">{e(x["years"])}</span><h2>{e(x["title"])}</h2><span class="read">{e(x["status"])}</span>'+('</a>' if x.get('link') else '</div>') for x in d['eras'])+'</div><p class="source">Stories may span more than one period. This framework leads to short introductions; the book collection preserves the fuller accounts, photographs and reference pages.</p>')
page('club.html','Our club',heading('PEOPLE · PARTICIPATION · CONTINUITY','Find your part of the club.','Explore a group’s stories and records. As the collection grows, recent achievements and activities will sit alongside its earlier history.')+'<div class="group-list">'+''.join(f'<details id="{g["id"]}"><summary>{e(g["title"])}<span>Explore this group</span></summary><div class="group-body"><p>{e(g["intro"])}</p><h3>Stories in this collection</h3>'+(''.join(f'<p><a href="{a["id"]}.html">{e(a["title"])}</a><br><span class="source">{e(a["date"])}</span></p>' for a in d['articles'] if g['id'] in a.get('groups',[])) or '<p class="quiet">Material for this group has yet to be added.</p>')+('<h3>A member’s own account</h3><p><a href="jack-carter.html">Jack Carter’s golfing life →</a></p>' if g['id'] in ('juniors','men','senior-men') else '')+group_book_links(g['id'])+('<h3>Trophy records</h3><p><a href="trophies.html">Explore seven supplied trophy records →</a></p>' if g['id']=='senior-men' else '')+'<h3>Recent records</h3>'+recent_records(g['id'])+'</div></details>' for g in d['groups'])+'</div><p class="source">The group names are an initial framework and can expand with the club. Current membership, bookings and event information remain on the <a href="https://www.taurangagolf.co.nz/">main club website</a>.</p>')
page('about.html','The book and this collection',heading('ACKNOWLEDGING THE FOUNDATION','From Dave’s book to a growing collection.','An extension of the work behind Pars from the Past, with space for the club’s continuing story.')+'''<div class="prose"><h2>Years of work, brought together</h2><p>Edited by David G. S. Mowat and published in 2014, <em>Pars from the Past</em> marked one hundred years of golf on the Gate Pa links. Dave brought together research, recollections, photographs and records to create a lasting account of the club.</p><p>The book acknowledges the earlier historical work of Joan Mirrielees and Deidre Hartley, as well as the many members and contributors who helped preserve this material. This website carries those acknowledgements forward.</p><h2>A foundation we can build on</h2><p>The initial historical stories are drawn from the book, with page references retained. As more material is added, its own sources and contributors will be identified. New contributions will remain distinguishable from the book’s account.</p><h2>History and the life of the club</h2><p>The historical framework gives visitors a way through time. Club group collections will also preserve more recent achievements, activities, photographs and records, so today’s club life can become part of tomorrow’s history.</p><p>Visitors can start with a short overview and choose how far to follow a subject. The structure is in place; the detail will grow a piece at a time.</p><p class="source">Book context: Pars from the Past (2014), title page, acknowledgements, foreword and introduction, pp. 1–5.</p><a href="sources.html">Sources and editorial notes →</a></div>''')
def book_source_links(pages):
 links=[]
 for label in pages.split(','):
  match=re.search(r'\d+',label)
  if match:links.append(f'<a href="documents/pars-from-the-past.pdf#page={int(match[0])}">Book pp. {e(label.strip())}</a>')
 return ' · '.join(links)
def timeline_rows(events):
 return '<ol class="timeline">'+''.join(f'<li><span class="year">{e(year)}</span><div><h2><a href="{id}.html">{e(title)}</a></h2><p>{e(text)}</p><p class="source">{book_source_links(pages)} · <a href="{id}.html">Read the story →</a></p></div></li>' for year,title,text,id,pages in events)+'</ol>'
by_id={a['id']:a for a in d['articles']}
def era_events(era):
 import re
 ranges={'beginnings':(1903,1923),'interwar':(1924,1945),'postwar':(1946,1959),'sixties':(1960,1979),'eighties':(1980,1999),'modern':(2000,2014)}
 lo,hi=ranges[era]
 return [t for t in d['timeline'] if (m:=re.search(r'\d{4}',t[0])) and lo<=int(m[0])<=hi]
def continuing_era(era):
 if era!='modern':return ''
 catalogue=json.loads((R/'content/catalogue.json').read_text())
 members=sorted((m for m in catalogue['life_members'] if m.get('added_after_book')),key=lambda m:(m['year'],m['name']))
 return '<section><h2>The continuing record after 2014</h2><ol class="timeline">'+''.join(f'<li><span class="year">{e(m["year"])}</span><div><h3><a href="person-{m["person_id"]}.html">{e(m["name"])} · Life membership</a></h3><p class="source">{e(m["source"])}</p></div></li>' for m in members)+'</ol><p><a href="windsor-green.html">November 2026 update: the fairway conversion is reported as almost complete →</a></p><aside class="note"><h2>Looking ahead</h2><p>What might the next chapter bring? Explore some simple possibilities for the game and the club, alongside Dave’s imagined second century.</p><a class="button" href="looking-ahead.html">Golf and the club’s future →</a></aside></section>'
page('timeline.html','Timeline',heading('1903–Future','The club’s story, in order.','Choose a period to unfold its milestones. Follow any event into its story, photographs and source notes.')+'<div class="chapter-nav">'+''.join(f'<a href="#{x["id"]}">{e(x["years"])}</a>' for x in d['eras'] if x.get('link'))+'</div>'+''.join(f'<details class="timeline-era" id="{x["id"]}"'+(' open' if x['id']=='beginnings' else '')+f'><summary>{e(x["years"])} · {e(x["title"])}</summary>'+timeline_rows(era_events(x['id']))+continuing_era(x['id'])+'</details>' for x in d['eras'] if x.get('link'))+'<aside class="note"><h2>History and an imagined future</h2><p>The book provides the historical backbone through 2014. Later recorded milestones continue the timeline. Looking ahead and Dave’s imagined second century provide a separate space for possibilities and discussion.</p><a href="daves-imagined-century.html">Read about the book’s ending →</a></aside>')
for era in d['eras']:
 if not era.get('link'):continue
 items=[a for a in d['articles'] if a.get('era')==era['id']]
 page(era['link'],era['title'],'<a class="back" href="history.html">← All historical chapters</a>'+heading(e(era['years']),e(era['title']),'Start with a story, or unfold the dated milestones below.')+cards(items)+'<details class="timeline-era"><summary>Follow this chapter’s timeline</summary>'+timeline_rows(era_events(era['id']))+'</details>'+continuing_era(era['id']))
def story_sections(category):
 result=''
 for era in d['eras']:
  items=[a for a in d['articles'] if a['category']==category and a.get('era')==era['id']]
  if items:result+=f'<section class="story-period"><span class="eyebrow">{e(era["years"])}</span><h2>{e(era["title"])}</h2>'+cards(items)+'</section>'
 return result
page('course.html','The Course',heading('1903–2014 · PLACES & PLAYING CONDITIONS','Finding room for golf.','From the Domain to Gate Pa, through redesign, water, trees, turf and changing facilities.')+story_sections('The Course'))
page('people.html','People & Stories',heading('PLAYERS · VOLUNTEERS · CLUB LIFE','People made it possible.','Choose a period or explore a club group. Each story keeps its source references close at hand.')+'<p><a href="jack-carter.html">Jack Carter’s own account →</a> · <a href="life-members.html">Life Members and their stories →</a></p><a href="club.html">Browse by club group →</a>'+story_sections('People & Stories'))
def document_archive():
 documents=json.loads((R/'content/documents.json').read_text())
 return heading('THE SOURCE COLLECTION','Documents in full.','Open a complete original document, including its photographs, tables and advertising. References elsewhere in the collection open these PDFs at the relevant page.')+'<div class="cards document-cards">'+''.join(f'<article class="card"><div><span class="eyebrow">{e(doc["credit"])}</span><h2>{e(doc["title"])}</h2><p>{e(doc["note"])}</p><p class="source">{doc["pages"]} pages · {doc["bytes"]/1048576:.1f} MB</p><p><a class="button" href="{doc["path"]}#page=1">Open complete PDF →</a></p><p><a href="{doc["path"]}" download>Download PDF</a></p></div></article>' for doc in documents)+'</div>'
page('archive.html','Documents and photographic archive',document_archive()+'<section class="page-heading"><span class="eyebrow">PHOTOGRAPHS &amp; DOCUMENTS</span><h2>Look closer at the record.</h2><p>Select an image to open it at full size. Dates and identifications follow the book; uncertain details remain marked.</p></section>'+'<aside class="note"><h2>Fresh material from the heritage folder</h2><p><a href="supplied-photographs.html">Five supplied photographs →</a> · <a href="trophies.html">Trophy records →</a> · <a href="life-members.html">Life Members →</a> · <a href="member-memories.html">Member memories →</a></p><h2>Photographs throughout the book</h2><p>The complete book collection contains 87 photographs and other substantial embedded images, grouped by chapter. These selected records below provide extra caption and dating notes.</p><a href="book-images.html">Browse all book images →</a></aside><div class="archive-grid">'+''.join(f'<article id="{x["id"]}">{fig(x["id"])}<h2>{e(x["title"])}</h2><p>{e(x["caption"])}</p><p class="source">Credit: {e(x["credit"])}<br>Source: Pars from the Past (2014), p. {e(x["page"])}.</p><p class="rights">Online reproduction: authorised by the project owner, 9 November 2026.</p></article>' for x in d['images'])+'</div>')
for x in d['articles']:
 source_links=x.get('book_pages') or [int(x['pages'].split('–')[0].split(',')[0])]
 original_reading='<p class="source-reading"><a href="book-page-'+f'{source_links[0]:03}'+'.html">Read the original book account →</a></p>'
 x=dict(x)
 refs=x.get('book_pages') or [int(x['pages'].split('–')[0].split(',')[0])]
 original_reading='<div class="source-reading"><strong>Explore the original source</strong><p>'+ ' · '.join(f'<a href="documents/pars-from-the-past.pdf#page={n}">Book p. {n}</a>' for n in refs)+'</p><p><a href="book-page-'+f'{refs[0]:03}'+'.html">Read the book account →</a></p>'+('<p><a href="documents/spalding-masters-1968-searchable.pdf#page=3">Open the complete 1968 Masters programme →</a></p>' if x['id']=='spalding-masters' else '')+'</div>'
 page(x['id']+'.html',x['title'],f'<a class="back" href="'+('course.html' if x['category']=='The Course' else 'people.html')+'">← '+x['category']+'</a>'+heading(e(x['date']),e(x['title']),e(x['intro']))+'<div class="article-layout"><article class="prose">'+''.join(f'<p>{e(p)}</p>' for p in x['paragraphs'])+original_reading+(' <p><a href="windsor-green.html">Windsor Green: the fairway conversion and water savings →</a></p>' if x['id'] in ['water-and-irrigation','greenkeepers','board-of-management','short-course'] else '')+'<div class="reader-tools">'+''.join(f'<a href="topic-{tid}.html">{e(tid.replace("-"," "))}</a>' for tid in x.get('topics',[]))+'</div>'+f'<aside class="note"><h2>Source note</h2><p>{e(x["source_note"]) if x.get("source_note") else "Adapted from Pars from the Past, edited by David G. S. Mowat (2014), pp. " + e(x["pages"]) + ". Newspaper reports are described as cited in the book; original issues have not yet been checked for this preview."}</p>{''.join(f'<p><a href="{e(src["url"])}">{e(src["title"])}</a></p>' for src in x.get('external_sources',[]))}<a href="sources.html">Editorial notes →</a></aside><div class="story-connections">{''.join(f'<a href="club.html#{g["id"]}">{e(g["title"])}</a>' for g in d['groups'] if g['id'] in x.get('groups',[]))}</div></article><aside>'+ (fig(x['image']) if x['image'] else '<div class="honours"><span class="eyebrow">EXPLORE FURTHER</span><h2>Follow the connections.</h2><p><a href="club.html">Club groups →</a></p><p><a href="timeline.html">The timeline →</a></p></div>')+'</aside></div>')
page('sources.html','Sources & editorial notes',heading('HOW THIS COLLECTION IS BUILT','The evidence behind the stories.','A working collection, with clear references and room for corrections.')+'''<div class="prose"><h2>Primary supplied source</h2><p><em>Pars from the Past: A History of the Tauranga Golf Club</em>, edited by David G. S. Mowat, published in 2014. Page numbers refer to printed book pages, which match the supplied PDF page numbers.</p><p><a href="documents/pars-from-the-past.pdf#page=1">The complete original book is available as a PDF</a> through the archive. The story introductions are newly written from the source. The separate book collection preserves its original accounts in attributed, page-by-page review transcriptions, with images and original-layout reference pages. Readers can choose the original PDF or the web text view.</p><h2>The club’s existing History page</h2><p>The <a href="https://www.taurangagolf.co.nz/history?ComeFromCat=1338">Tauranga Golf Club History page</a> is an accepted historical reference alongside Mowat’s book. It confirms that the club dates from 1904 and has occupied its Racecourse Reserve home at Gate Pā since 1914.</p><h2>Our historical foundation</h2><p>Mowat’s extensively researched book is treated as generally affirmed historical material and the primary reference for this collection. Other historical contributions are compared against his original account and the club’s official history wherever they cover the subject. Rare exceptions require an explicit explanation and supporting evidence. Material beyond the book’s coverage keeps its own source and contributor attribution.</p><h2>New material from the club heritage folder</h2><p>The <a href="trophies.html">trophy register</a> transcribes seven separately supplied records, including 168 year entries and their gaps. These are partial records, not a complete verified results database. Context links lead back to Mowat; differences such as the Ron Galloway Cup’s 1953 heading and the book’s 1954 donation account remain visible.</p><p><a href="supplied-photographs.html">Five separately supplied photographs</a> retain their captions and source filenames. The <a href="life-members.html">Life Members page</a> makes the book’s 2014 roll easier to find. <a href="member-memories.html">Member memories</a> uses prompts from the supplied interview template; it does not claim that interviews have already taken place.</p><h2>Member histories supplied 10 November 2026</h2><p><a href="jack-carter.html">Jack Carter’s golfing life</a> preserves his undated personal account from JACK CARTERS GOLF HISTORY.docx. His 2019 Life Membership is added separately from the book’s 2014 roll. References to 46 years of involvement describe the time of writing; the recollection is not treated as a current statement of club policy.</p><p>Life Members Landscape.pdf is a 21-page compilation of profiles, club notices, correspondence and third-party clippings. Ten <a href="life-members.html">Life Member profiles</a> summarise the relevant material, with PDF page references and comparison links to Mowat. Later notices concerning Noel Copestake in 2016 and Phyll Sandlant in 2023 extend the record beyond the book. Private email details and signatures are omitted, and the compilation itself is not offered for download.</p><h2>The 1968 Spalding Masters programme</h2><p>The programme adds contemporary records and photographs of players, greenkeepers and the course, together with advertising that places golf within Tauranga life. Its material is indexed across subjects; apparent conflicts with the book remain identified. Programme photographs were authorised for publication on 10 November 2026.</p><p><a href="source-spalding-1968.html">Explore the programme and photographs →</a></p><h2>Dates and gaps</h2><p>1903 marks Brown’s arrival, not a claimed club foundation. The book and the club’s official history support 1904 as the foundation year; 1914 marks the move to Gate Pā. Its introduction explains the lack of early minute books and the use of recollections and newspaper research. Newspaper originals have not yet been independently checked for this preview.</p><p>The undated golfing-party and Avenue images are contextual material. Their inclusion does not establish a 1903–1923 date. The Domain course card also has a dating question noted by the book itself.</p><h2>Additional source for nine-hole golf</h2><p><a href="https://www.sunlive.co.nz/news/87217-a-hole-100.html">Luke Balvert, “A hole in 100”, SunLive, 15 November 2014</a>, identifies Patsy Hankins’s national role and her approach to Phyll Sandlant in 1998. The nine-hole story distinguishes this report from the book’s local account.</p><h2>Reading the original book</h2><p><a href="book.html">The complete book collection</a> retains Dave’s text and its own period context. Recollections, opinions, terminology and historical rules are not rewritten as current facts. The transcription removes running headers and stray layout characters; it has not been fully proofread. Multi-column honours and trophy reference pages retain their printed layout as images, alongside searchable text that must not be used to infer column relationships.</p><p>The last chapter explicitly includes an imagined future. Predictions are labelled at chapter and page level and do not appear in the factual timeline.</p><h2>Details still to check</h2><p>The source notes in the redesign, wartime, clubhouse and Veterans’ stories identify conflicting details within the book. They concern the lease chronology, wartime championship years, final clubhouse cost and a tournament date. These questions remain visible for members to help resolve.</p><h2>Image register</h2><p>Each <a href="archive.html">archive record</a> includes its book page, available credit, date status and reproduction authorisation. Images were extracted without generating or replacing historical detail; only web sizing and JPEG compression were applied.</p><h2>Review edition and image permission</h2><p>The project owner authorised all photographs and images for publication on 9 November 2026. Mowat’s book and the club’s official history provide the accepted historical foundation. New records and identifications remain open to specific corrections. This is a member review edition, shared to invite corrections and development suggestions. Review status allows the collection and its presentation to develop; it does not mean that the book’s researched history is treated as unconfirmed.</p><h2>Alongside the main website</h2><p>The existing club History page can remain a short introduction, linking to this collection when ready. This separate static collection does not change bookings, membership, news or the club’s existing navigation. Any future address or hosting arrangement is still to be agreed.</p></div>''')
page('feedback.html','Feedback & contributions',heading('MEMBER REVIEW EDITION','Help put more skin on the bones.','Tell us what works, what needs correcting, and which parts of the club’s story we should develop next.')+'''<div class="prose"><h2>What would be useful?</h2><ul><li>Names, dates or places to correct, with a source if you have one.</li><li>People missing from a story or a photograph.</li><li>Ideas for the Juniors, Ladies, Ladies 9 Hole, Men and Senior Men collections.</li><li>Recent records, photographs or results to preserve.</li><li>Anything difficult to find or read on your phone or computer.</li></ul><h2>Leave a note on GitHub</h2><p><a class="button" href="https://github.com/bwucee/Tauranga-Golf-Club-Heritage/issues/new?template=member-feedback.yml">Add feedback ↗</a></p><p>A free GitHub account is needed to submit a note. You can <a href="https://github.com/bwucee/Tauranga-Golf-Club-Heritage/issues">browse the existing feedback</a> without signing in. Feedback there is public.</p><h2>Prefer to send your thoughts directly?</h2><p>Reply to the club member who shared this preview with you. Include the page title or link, your suggested change and any source or photograph you would like considered. This website does not collect messages through a form.</p><h2>Contributing material</h2><p>Please include the event date, names of people, the club group it relates to, and who supplied the material. For photographs, identify the photographer or owner where known and say whether they have agreed to online use. New submissions will be reviewed before joining the collection.</p><h2>What this preview covers</h2><p>Six historical chapters cover the story through 2014. All 25 chapters of Dave’s book, front matter and appendices are available in the book collection, alongside shorter story introductions. The imagined future in the final chapter is labelled and excluded from the historical timeline. New contributors will be credited as the collection grows.</p></div>''')
